type LocaleContextValue={locale:Locale|null;ready:boolean;dir:"ltr"|"rtl";t:(key:string,vars?:Vars)=>string;setLocale:(locale:Locale)=>void;options:typeof localeOptions};
const LocaleContext=createContext<LocaleContextValue|null>(null);
function validLocale(value:string|null):Locale|null{return value==="en"||value==="ar"||value==="he"?value:null;}
export function LocaleProvider({children}:{children:ReactNode}){
 const [locale,setLocaleState]=useState<Locale>("ar");const [ready,setReady]=useState(false);
 const localeTransitionTimer=useRef<number|undefined>(undefined);
 // Hydrate the persisted locale once on the client; this is the boundary between SSR and browser storage.
 // eslint-disable-next-line react-hooks/set-state-in-effect
 useEffect(()=>{let stored:Locale|null=null;try{stored=validLocale(window.localStorage.getItem("jeroam-locale"));}catch{/* storage can be disabled; keep the selector usable */}if(stored)setLocaleState(stored);setReady(true);},[]);
 useEffect(()=>{if(!locale)return;const config=localeConfig[locale];document.documentElement.lang=config.htmlLang;document.documentElement.dir=config.dir;document.body.dir=config.dir;},[locale]);
 useEffect(()=>{if(!locale)return;document.title=dictionaries[locale]["common.metaTitle"]??document.title;const description=document.querySelector<HTMLMetaElement>('meta[name="description"]');if(description){description.content=dictionaries[locale]["common.metaDescription"]??description.content;}},[locale]);
 const setLocale=(next:Locale)=>{if(next!==locale&&typeof window!=="undefined"&&!window.matchMedia("(prefers-reduced-motion: reduce)").matches){document.documentElement.classList.add("locale-transition");window.clearTimeout(localeTransitionTimer.current);localeTransitionTimer.current=window.setTimeout(()=>document.documentElement.classList.remove("locale-transition"),220);}setLocaleState(next);try{window.localStorage.setItem("jeroam-locale",next);}catch{}};
 const value=useMemo<LocaleContextValue>(()=>({locale,ready,dir:locale?localeConfig[locale].dir:"ltr",t:(key,vars={})=>{const template=dictionaries[locale??"en"][key]??dictionaries.en[key]??(key.startsWith("area.")||key.startsWith("category.")||key.startsWith("theme.")||key.startsWith("difficulty.")||key.startsWith("interest.")?key.slice(key.indexOf(".")+1):key);return template.replace(/\{(\w+)\}/g,(_,name)=>String(vars[name]??""));},setLocale,options:localeOptions}),[locale,ready]);
 return <LocaleContext.Provider value={value}>{children}</LocaleContext.Provider>;
}
export function useI18n(){const value=useContext(LocaleContext);if(!value)throw Error("Locale provider missing");return value;}

/** Render a stored language preference in the language currently used by the interface. */
export function localizedLanguageName(value:string,locale:Locale|null|undefined):string{
 return languageLabels[value]?.[locale??"en"]??value;
}

