/** Keep the generated starter title in the active interface language. */
export function localizedTripTitle(value:string,locale:Locale|null|undefined):string{
 if(!defaultTripTitles.has(value))return value;
 return locale==="ar"?"رحلتي في القدس":locale==="he"?"המסע שלי בירושלים":"My Jerusalem journey";
}

export function LanguageSelector(){
 const {t,setLocale}=useI18n();const [choice,setChoice]=useState<Locale>("en");
 return <main className="language-gate"><div className="language-gate-art"><div className="language-gate-mark"><Compass size={30}/></div><div><span className="eyebrow light"><span/>{t("selector.jeroamMark")}</span><p>{t("selector.brand")}</p></div></div><section className="language-gate-panel"><span className="eyebrow">{t("selector.eyebrow")}</span><h1>{t("selector.title").split("\n").map((line,index)=><span key={`${line}-${index}`}>{index>0&&<br/>}{line}</span>)}</h1><p>{t("selector.copy")}</p><div className="language-gate-options" role="radiogroup" aria-label={t("nav.language")}>{localeOptions.map(option=><button type="button" role="radio" aria-checked={choice===option} className={choice===option?"selected":""} onClick={()=>setChoice(option)} key={option}><Globe2 size={20}/><span><strong>{localeConfig[option].nativeName}</strong><small>{localeConfig[option].englishName}</small></span>{choice===option&&<Check size={16}/>}</button>)}</div><button type="button" className="button language-gate-continue" onClick={()=>setLocale(choice)}>{t("selector.continue",{language:localeConfig[choice].nativeName})}<ArrowRight size={17}/></button><small className="language-gate-note">{t("selector.note")}</small></section></main>;
}

export function LanguageSwitcher(){
 const {locale,setLocale}=useI18n();
 const current=locale??"ar";
 return (
  <div
   className="language-switcher"
   style={{
    display:"inline-flex",
    alignItems:"center",
    background:"#ffffff",
    border:"1.5px solid rgba(245,166,35,0.45)",
    borderRadius:"100px",
    padding:"2px 3px",
    gap:"2px",
    boxShadow:"0 2px 8px rgba(14,56,76,0.04)"
   }}
  >
   <button
    type="button"
    aria-label="العربية"
    onClick={()=>setLocale("ar")}
    style={{
     background:current==="ar"?"linear-gradient(135deg, #f5a623 0%, #ffba3b 100%)":"transparent",
     color:current==="ar"?"#0e384c":"#5a7585",
     border:"none",
     borderRadius:"100px",
     padding:"4px 9px",
     fontSize:"0.76rem",
     fontWeight:current==="ar"?800:600,
     cursor:"pointer",
     transition:"all 0.15s ease"
    }}
   >
    العربية
   </button>
   <button
    type="button"
    aria-label="English"
    onClick={()=>setLocale("en")}
    style={{
     background:current==="en"?"linear-gradient(135deg, #f5a623 0%, #ffba3b 100%)":"transparent",
     color:current==="en"?"#0e384c":"#5a7585",
     border:"none",
     borderRadius:"100px",
     padding:"4px 9px",
     fontSize:"0.76rem",
     fontWeight:current==="en"?800:600,
     cursor:"pointer",
     transition:"all 0.15s ease"
    }}
   >
    EN
   </button>
   <button
    type="button"
    aria-label="עברית"
    onClick={()=>setLocale("he")}
    style={{
     background:current==="he"?"linear-gradient(135deg, #f5a623 0%, #ffba3b 100%)":"transparent",
     color:current==="he"?"#0e384c":"#5a7585",
     border:"none",
     borderRadius:"100px",
     padding:"4px 9px",
     fontSize:"0.76rem",
     fontWeight:current==="he"?800:600,
     cursor:"pointer",
     transition:"all 0.15s ease"
    }}
   >
    עברית
   </button>
  </div>
 );
}

